    float X, Y, Z;
    C3DVector() {}
    C3DVector(float x, float y, float z) : X(x), Y(y), Z(z) {}
    C3DVector operator+(const C3DVector& o) const { return C3DVector(X + o.X, Y + o.Y, Z + o.Z); }
};
enum ENavigatorReturn { NAV_FAILED = 0, NAV_ARRIVED = 1, NAV_MOVING = 2, NAV_OTHER = 3 };
